import {quadUV} from './perspective.js';
import {createSurface} from './surface.js';
const cache=new WeakMap();
export function repairSpot(canvas,stroke){const x=canvas.getContext('2d',{willReadFrequently:true}),w=canvas.width,h=canvas.height,r=Math.max(2,Math.min(Math.min(w,h)/5,stroke.r*Math.max(w,h))),cx=stroke.x*w,cy=stroke.y*h,data=x.getImageData(0,0,w,h),a=data.data;let sx=stroke.sx*w,sy=stroke.sy*h;
 const sample=(px,py)=>{const i=(Math.max(0,Math.min(h-1,Math.round(py)))*w+Math.max(0,Math.min(w-1,Math.round(px))))*4;return [a[i],a[i+1],a[i+2]];};
 if(stroke.auto){let best=Infinity;for(let j=0;j<20;j++){const angle=j/20*Math.PI*2,rr=r*(2.6+(j%3)*.6),tx=cx+Math.cos(angle)*rr,ty=cy+Math.sin(angle)*rr;if(tx-r<0||ty-r<0||tx+r>=w||ty+r>=h)continue;let cost=0;for(let k=0;k<16;k++){const q=k/16*Math.PI*2,dx=Math.cos(q)*r*.9,dy=Math.sin(q)*r*.9,b=sample(cx+dx,cy+dy),c=sample(tx+dx,ty+dy);cost+=b.reduce((v,n,i)=>v+(n-c[i])**2,0);}if(cost<best){best=cost;sx=tx;sy=ty;}}if(!Number.isFinite(best)){sx=Math.max(r,Math.min(w-r-1,cx+r*2.6));sy=Math.max(r,Math.min(h-r-1,cy));}}
 const source=new Uint8ClampedArray(a),meanA=[0,0,0],meanB=[0,0,0];for(let k=0;k<32;k++){const angle=k/32*Math.PI*2,dx=Math.cos(angle)*r*.85,dy=Math.sin(angle)*r*.85,b=sample(cx+dx,cy+dy),c=sample(sx+dx,sy+dy);for(let q=0;q<3;q++){meanA[q]+=b[q]/32;meanB[q]+=c[q]/32;}}
 const strength=stroke.strength??1;for(let py=Math.max(0,Math.floor(cy-r));py<Math.min(h,cy+r);py++)for(let px=Math.max(0,Math.floor(cx-r));px<Math.min(w,cx+r);px++){const dx=px-cx,dy=py-cy,d=Math.hypot(dx,dy)/r;if(d>=1)continue;const weight=Math.min(1,(1-d)/.35)*strength,i=(py*w+px)*4,j=(Math.max(0,Math.min(h-1,Math.round(sy+dy)))*w+Math.max(0,Math.min(w-1,Math.round(sx+dx))))*4;for(let k=0;k<3;k++){const value=source[j+k]+(stroke.mode==='clone'?0:meanA[k]-meanB[k]);a[i+k]=a[i+k]*(1-weight)+value*weight;}}x.putImageData(data,0,0);return canvas;}
export function repairedImage(image,strokes){if(!strokes?.length)return image;const signature=JSON.stringify(strokes),old=cache.get(image);if(old?.signature===signature)return old.canvas;if(old&&strokes.length>old.count&&JSON.stringify(strokes.slice(0,old.count))===old.signature){for(const stroke of strokes.slice(old.count))repairSpot(old.canvas,stroke);old.signature=signature;old.count=strokes.length;return old.canvas;}const scale=Math.min(1,4096/Math.max(image.width,image.height));const out=createSurface(Math.max(1,Math.round(image.width*scale)),Math.max(1,Math.round(image.height*scale)));out.getContext('2d').drawImage(image,0,0,out.width,out.height);for(const stroke of strokes)repairSpot(out,stroke);cache.set(image,{signature,canvas:out,count:strokes.length});return out;}
export function imagePoint(layer,image,point){const a=-layer.rotation*Math.PI/180,dx=point.x-layer.x,dy=point.y-layer.y,u0=(dx*Math.cos(a)-dy*Math.sin(a))/layer.w+.5,v0=(dx*Math.sin(a)+dy*Math.cos(a))/layer.h+.5;const [u,v]=layer.quad?quadUV(layer.quad,u0,v0):[u0,v0];if(u<0||v<0||u>1||v>1)return null;let cw=image.width,ch=image.height,ox=0,oy=0;if(layer.fit==='cover'){const scale=Math.max(layer.w/image.width,layer.h/image.height)*(layer.crop?.zoom||1);cw=layer.w/scale;ch=layer.h/scale;ox=(image.width-cw)*(layer.crop?.x??50)/100;oy=(image.height-ch)*(layer.crop?.y??50)/100;}return {x:(ox+u*cw)/image.width,y:(oy+v*ch)/image.height,pixelsPerDocument:cw/layer.w};}
